//! The Vulkan Video arm converts each picture with the range and matrix its
//! stream signals: clips another encoder wrote — full range, BT.601, and
//! signalling nothing at HD and at SD — come back as the bars they encode, and
//! each decoded picture names the colour it was converted with. The clips are
//! regenerated by `tests/fixtures/third_party_colour_signalling_clips/
//! regenerate_the_third_party_colour_signalling_clips.sh`.
//!
//! Rig tier: it needs a device with Vulkan Video decode queues.

#![cfg(target_os = "linux")]

use std::path::Path;
use std::sync::OnceLock;

use streamlib::sdk::color::H273ColorVui;
use streamlib::sdk::color::h273_color_vui::matrix;
use streamlib::sdk::context::{
    DecodedVideoPictureInPooledPixelBuffer, GpuContext, VideoCodecElementaryStream,
    VideoDecodeSessionRequest, probe_video_codec_backend,
};
use streamlib::sdk::engine::HostGpuDeviceExt as _;

#[path = "support/rig_only_capability_skip.rs"]
mod rig_only_capability_skip;

/// The bars every clip encodes, left to right, as the regeneration script
/// writes them.
const ENCODED_BAR_RGB: [[u8; 3]; 5] = [
    [0xC0, 0x20, 0x20],
    [0x20, 0xC0, 0x20],
    [0x20, 0x20, 0xC0],
    [0xC8, 0xC8, 0xC8],
    [0x10, 0x10, 0x10],
];

/// How far a decoded bar may sit from the encoded one on any channel. ffmpeg's own
/// decode of these clips lands within 2; reading one with the other range or
/// matrix moves at least one bar of every clip by more than 10.
const BAR_CHANNEL_TOLERANCE: u8 = 6;

/// One checked-in clip and the colour its pictures are in.
struct ColourSignallingClip {
    file_name: &'static str,
    elementary_stream: VideoCodecElementaryStream,
    width: u32,
    height: u32,
    sample_matrix_coefficients: u8,
    sample_full_range: bool,
}

const H264_CLIPS: &[ColourSignallingClip] = &[
    ColourSignallingClip {
        file_name: "h264_bt709_full_range_1280x720.annexb",
        elementary_stream: VideoCodecElementaryStream::H264,
        width: 1280,
        height: 720,
        sample_matrix_coefficients: matrix::BT709,
        sample_full_range: true,
    },
    ColourSignallingClip {
        file_name: "h264_bt601_limited_range_1280x720.annexb",
        elementary_stream: VideoCodecElementaryStream::H264,
        width: 1280,
        height: 720,
        sample_matrix_coefficients: matrix::SMPTE170M,
        sample_full_range: false,
    },
    ColourSignallingClip {
        file_name: "h264_unsignalled_1280x720.annexb",
        elementary_stream: VideoCodecElementaryStream::H264,
        width: 1280,
        height: 720,
        sample_matrix_coefficients: matrix::BT709,
        sample_full_range: false,
    },
    ColourSignallingClip {
        file_name: "h264_unsignalled_640x480.annexb",
        elementary_stream: VideoCodecElementaryStream::H264,
        width: 640,
        height: 480,
        sample_matrix_coefficients: matrix::SMPTE170M,
        sample_full_range: false,
    },
];

const H265_CLIPS: &[ColourSignallingClip] = &[
    ColourSignallingClip {
        file_name: "h265_bt709_full_range_1280x720.annexb",
        elementary_stream: VideoCodecElementaryStream::H265,
        width: 1280,
        height: 720,
        sample_matrix_coefficients: matrix::BT709,
        sample_full_range: true,
    },
    ColourSignallingClip {
        file_name: "h265_bt601_limited_range_1280x720.annexb",
        elementary_stream: VideoCodecElementaryStream::H265,
        width: 1280,
        height: 720,
        sample_matrix_coefficients: matrix::SMPTE170M,
        sample_full_range: false,
    },
];

fn gpu_context() -> &'static GpuContext {
    static GPU_CONTEXT: OnceLock<GpuContext> = OnceLock::new();
    GPU_CONTEXT.get_or_init(|| GpuContext::init_for_platform().expect("a Vulkan device"))
}

/// Whether the device decodes Vulkan Video, naming its absence when it does not.
fn skip_unless_the_device_decodes_vulkan_video() -> bool {
    rig_only_capability_skip::skip_unless_this_machine_has(
        rig_only_capability_skip::RigOnlyCapability::VulkanVideo,
        gpu_context()
            .device()
            .vulkan_device()
            .supports_video_decode(),
    )
}

/// The one picture the clip's single access unit decodes to.
fn decode_the_clip(clip: &ColourSignallingClip) -> DecodedVideoPictureInPooledPixelBuffer {
    let access_unit = std::fs::read(
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/third_party_colour_signalling_clips")
            .join(clip.file_name),
    )
    .expect("the checked-in clip");
    let backend = probe_video_codec_backend();
    let mut decode_session = gpu_context()
        .limited_access()
        .escalate(|full| {
            backend.open_decode_session(
                full,
                &VideoDecodeSessionRequest {
                    elementary_stream: clip.elementary_stream,
                    maximum_coded_extent: None,
                    processor_id_of_the_decoding_node: "colour-signalling-clip-decoder".to_string(),
                },
            )
        })
        .expect("a decode session");
    let mut decoded_pictures = Vec::new();
    decode_session
        .decode_annex_b_access_unit(&access_unit, &mut decoded_pictures)
        .unwrap_or_else(|refusal| panic!("{}: {refusal}", clip.file_name));
    assert_eq!(
        decoded_pictures.len(),
        1,
        "{}: one access unit decodes to one picture",
        clip.file_name
    );
    decoded_pictures.remove(0)
}

/// Each bar's median colour over a 16×16 patch at its centre.
fn median_bar_rgb(decoded_rgba: &[u8], width: u32, height: u32) -> [[u8; 3]; 5] {
    let bar_width = width / 5;
    std::array::from_fn(|bar_index| {
        let centre_x = bar_width * bar_index as u32 + bar_width / 2;
        let centre_y = height / 2;
        std::array::from_fn(|channel| {
            let mut samples: Vec<u8> = (centre_y - 8..centre_y + 8)
                .flat_map(|y| (centre_x - 8..centre_x + 8).map(move |x| (x, y)))
                .map(|(x, y)| decoded_rgba[((y * width + x) * 4) as usize + channel])
                .collect();
            samples.sort_unstable();
            samples[samples.len() / 2]
        })
    })
}

/// What went wrong decoding `clip`, if anything.
fn how_the_clip_decoded_wrong(clip: &ColourSignallingClip) -> Option<String> {
    let decoded_picture = decode_the_clip(clip);
    if (decoded_picture.width, decoded_picture.height) != (clip.width, clip.height) {
        return Some(format!(
            "{}: decoded at {}x{}, not {}x{}",
            clip.file_name, decoded_picture.width, decoded_picture.height, clip.width, clip.height
        ));
    }
    // SAFETY: the pooled picture is held, host-readable once decode hands it
    // back, and exactly `width × height × 4` bytes.
    let decoded_rgba = unsafe {
        std::slice::from_raw_parts(
            decoded_picture.pixel_buffer.plane_base_address(0),
            clip.width as usize * clip.height as usize * 4,
        )
    };
    let decoded_bars = median_bar_rgb(decoded_rgba, clip.width, clip.height);
    let bars_off_by_more_than_the_tolerance =
        decoded_bars
            .iter()
            .zip(ENCODED_BAR_RGB)
            .any(|(decoded, encoded)| {
                decoded
                    .iter()
                    .zip(encoded)
                    .any(|(decoded_channel, encoded_channel)| {
                        decoded_channel.abs_diff(encoded_channel) > BAR_CHANNEL_TOLERANCE
                    })
            });
    if bars_off_by_more_than_the_tolerance {
        return Some(format!(
            "{}: decoded bars {decoded_bars:?}, encoded {ENCODED_BAR_RGB:?}",
            clip.file_name
        ));
    }
    let H273ColorVui {
        matrix, full_range, ..
    } = decoded_picture.decoded_picture_color_vui;
    if (matrix, full_range)
        != (
            Some(clip.sample_matrix_coefficients),
            Some(clip.sample_full_range),
        )
    {
        return Some(format!(
            "{}: the picture says it was converted with matrix {matrix:?}, full range \
             {full_range:?}; its samples are matrix {}, full range {}",
            clip.file_name, clip.sample_matrix_coefficients, clip.sample_full_range
        ));
    }
    None
}

fn every_clip_decodes_with_the_colour_it_signals(clips: &[ColourSignallingClip]) {
    let wrong_decodes: Vec<String> = clips
        .iter()
        .filter_map(how_the_clip_decoded_wrong)
        .collect();
    assert!(wrong_decodes.is_empty(), "{wrong_decodes:#?}");
}

#[test]
#[cfg_attr(
    not(feature = "hardware-tests"),
    ignore = "hardware integration — needs Vulkan Video decode queues; see docs/testing-hardware.md"
)]
fn vulkan_video_decodes_each_h264_clip_with_the_colour_it_signals() {
    if skip_unless_the_device_decodes_vulkan_video() {
        return;
    }
    every_clip_decodes_with_the_colour_it_signals(H264_CLIPS);
}

#[test]
#[cfg_attr(
    not(feature = "hardware-tests"),
    ignore = "hardware integration — needs Vulkan Video decode queues; see docs/testing-hardware.md"
)]
fn vulkan_video_decodes_each_h265_clip_with_the_colour_it_signals() {
    if skip_unless_the_device_decodes_vulkan_video() {
        return;
    }
    every_clip_decodes_with_the_colour_it_signals(H265_CLIPS);
}
